INSERT INTO `item` (`id`, `category_id`, `sub_category_id`, `brand_id`, `section_id`, `name`, `barcode`, `length`, `height`, `width`, `regular_price`, `minimum_order_quantity`, `sales_price`, `cost_price`, `thumbnail`, `details`, `specification_details`, `sales_type`, `is_published`, `car_company_id`, `car_brand_id`, `car_model_id`, `created_by`, `updated_by`, `soft_delete`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 1, 1, 'FUEL® - D552 TROPHY 1PC Graphite with Matte Black Bead Ring', '1010101010', '6', '12', '3', 0, 1, 0, 10000, 'itemImage/ZnVlbC10cm9waHktZ3JhcGhpdGUtbWF0dGUtYmxhY2stYmVhZC1yaW5nXzEuanBnMjgzNDAw.jpg', 'D552 TROPHY 1PC Graphite with Matte Black Bead Ring Wheels by Fuel®. These astonishing monoblock wheels would fit someone who is looking for strength, performance, and style. Made from just one piece of metal using leading-edge equipment, these wheels guarantee maximum durability. They feature an exceptionally stiff construction and technical perfection. Plus, the wheels are designed to deliver remarkable operation both on the streets and trails.', '', 'featured', 1, '1', '1', '1', 'superadmin', 'superadmin', 0, '2021-01-26 05:47:45', '2021-06-07 12:26:13'),
(2, 1, 1, 2, 1, 'SUPERSPEED® - RF03RR Matte Black', '11110000', '6', '12', '3', 150, 1, 300, 500, 'itemImage/c3VwZXJzcGVlZC13aGVlbHMtcmYwM3JyLW1hdHRlLWJsYWNrXzEuanBnODAxNzk2.jpg', 'RF03RR Matte Black Wheels by SUPERSPEED®. Built to meet and exceed industry standards, Superspeed wheels are the right choice for those who value great performance and impeccable style. Combining superior quality and durable construction, they can handle any conditions. Whether you are racing or touring, Superspeed wheels deliver the ultimate in safety and comfort.', '', 'featured', 0, '2', '2', '2', 'superadmin', 'superadmin', 0, '2021-01-26 06:33:48', '2021-06-03 13:13:46'),
(3, 1, 1, 2, 1, 'SUPERSPEED® - RF03RR White', '0001111', '5', '10', '2.5', 19000, 1, 19000, 13000, 'itemImage/c3VwZXJzcGVlZC13aGVlbHMtcmYwM3JyLXNwZWVkLXdoaXRlXzEuanBnNzU1MDI5.jpg', 'RF03RR White Wheels by SUPERSPEED®. Built to meet and exceed industry standards, Superspeed wheels are the right choice for those who value great performance and impeccable style. Combining superior quality and durable construction, they can handle any conditions. Whether you are racing or touring, Superspeed wheels deliver the ultimate in safety and comfort.', '', 'special', 0, '2', '2', '2', 'superadmin', 'superadmin', 0, '2021-01-26 07:24:18', '2021-01-26 09:13:11'),
(4, 2, 2, 3, 2, 'PROCONTACT TX', '123456', '18', '25', '20', 7215, 1, 7000, 5000, 'itemImage/Y29udGluZW50YWwtcHJvY29udGFjdC10eF8xLmpwZzU1NDE5Nw==.jpg', 'PROCONTACT TX Tires by CONTINENTAL®. Season: All Season. Type: Fuel Efficient. The ProContact TX is an all-season touring tire that comes as original equipment on many sophisticated coupes and luxury performance sedans. Its unique tread design produces impressive traction performance along with solid steering stability and handling.\r\nCar safety starts with the car\'s tires. The demands placed on them are enormous since one meter of braking distance can make a crucial difference. After all, the car\'s full braking force is transmitted to the road solely via four postcard-size contact patches. Continental passenger and light truck tires provide superb vehicle-road contact in all types of weather.', '', 'onsale', 0, '3', '3', '4', 'superadmin', 'superadmin', 0, '2021-01-26 10:27:09', '2021-05-20 04:04:29'),
(5, 2, 3, 3, 2, 'ZEON RS3-G1', '122356', '20', '22', '18', 8900, 1, 1300, 500, 'itemImage/Y29vcGVyLXplb24tcnMzLWcxXzEuanBnNjcwNzA4.jpg', 'Forget about those unnecessary expenses from the budget associated with switching between summer and winter tires. All-season tires are an ultimate traction solution for any car or truck owner as they give them freedom from the money-spending cycle, providing a reliable, year-round service. The tires are designed to work perfectly in any weather conditions: during low temperatures in the wet or snow and high temperatures in the dry. Such superb performance is assured thanks to a tough, abrasion-resistant construction of the tires and their unique tread design. What you get is superb cornering and steering response, enhanced traction, and quiet ride. Stop throwing your money and time away and go with the All-Season Tires that are offered on our website at more than reasonable prices', '', 'featured', 1, '3', '4', '3', 'superadmin', 'superadmin', 0, '2021-01-26 10:41:53', '2021-05-20 03:10:39'),
(6, 3, 4, 4, 2, 'Spec-D® - Custom Headlights', '22356', '11', '16', '10', 3300, 1, 3000, NULL, 'itemImage/Y3VzdG9tLWhlYWRsaWdodHNfMS5qcGc4MjAxMjQ=.jpg', 'Custom Headlights by Spec-D®. Improve your vision at night and in inclement weather and upgrade your vehicle’s appearance with these bolt-on headlight assemblies. The projector beam headlights will produce a sharper, more focused beam of light for safer driving, and the custom headlight housing will give your car or truck a unique, distinctive look.\r\nProjector headlights provide superior illumination, which enables better vision in darkness and inclement weather, for safer driving. This is because the bulb in a projector headlight is positioned in front of an elliptical-shaped reflector. Where a conventional parabolic type reflector reflects light outward in a dispersed pattern, the elliptical reflector reflects the light toward a single focal point in front of the bulb. Projector headlights produce a sharper, more focused beam of light with less scatter loss', '', 'featured', 1, '3', '5', '6', 'superadmin', 'superadmin', 0, '2021-01-26 10:58:21', '2021-01-26 10:58:21'),
(7, 3, 5, 4, 2, 'Projector Headlights', '123325', '20', '20', '20', 3875, 1, 1600, 1500, 'itemImage/cHJvamVjdG9yLWhlYWRsaWdodHMtd2l0aC1sZWRzXzEuanBnMjk2MTkw.jpg', 'Custom Headlights by Spec-D®. Improve your vision at night and in inclement weather and upgrade your vehicle’s appearance with these bolt-on headlight assemblies. The projector beam headlights will produce a sharper, more focused beam of light for safer driving, and the custom headlight housing will give your car or truck a unique, distinctive look.', '', 'featured', 1, '4', '6', '7', 'superadmin', 'superadmin', 0, '2021-01-26 11:10:35', '2021-02-01 10:21:58'),
(8, 4, 6, 5, 2, 'Exhaust System', '56565', '22', '24', '18', 14500, 1, 1200, 1000, 'itemImage/MTAxNDAxNF8xLmpwZzU0MzMzMA==.jpg', 'Exhaust System by Borla®. This unique system allows you to adjust your level of sound and power, from quiet and restrictive to louder and free flowing. It features a patented Borla straight-through muffler and mandrel bent pipes constructed from aircraft grade austenitic stainless steel, and it’s backed by Borla’s unequalled one million mile warranty.', '', 'featured', 0, '4', '7', '8', 'superadmin', 'superadmin', 0, '2021-01-26 11:18:42', '2021-05-29 12:42:14'),
(9, 4, 7, 6, 2, 'Competition Core Stainless Steel Silver Exhaust Muffler', '56666654', '33', '28', '22', 12500, 1, 700, 500, 'itemImage/MTQ4MDZfMS5qcGc4MzI0Njg=.jpg', 'Universal Competition Core Stainless Steel Silver Exhaust Muffler by MagnaFlow®. Muffler Body Length: 14\". Muffler Sound: Aggressive / Loud. Muffler Configuration: Center - Center. These are mufflers for souped-up street machines. These mufflers look and sound great, making them perfect for the high performance street-legal car. Remove sound dampener for pure off-street race roar.The high shine mufflers of the Street Series not only look good. The also sound good, emitting a smooth, deep tone. And they offer improved performance over OEM equipment.', '', 'featured', 1, '4', '8', '9', 'superadmin', 'superadmin', 0, '2021-01-26 11:25:30', '2021-05-30 10:36:07'),
(10, 4, 8, 7, 2, 'Cat4ward Shorty Exhaust Headers', '464646', '10', '20', '22', 21800, 1, 21000, NULL, 'itemImage/MTk2NHMtMWp0XzEuanBnNDU5MTQw.jpg', 'Cat4ward Shorty Exhaust Headers by JBA®. JBA shorty headers are one of the best performance upgrades available for any application. Hot Rod magazine rated headers as one of the top 10 power parts installed on a vehicle. JBA shorty headers are significantly less restrictive than the stock manifolds on a vehicle and dramatically increase the power and efficiency of an engine. JBA\'s original shorty design is an innovation of the old long tube header. The new shorty designs yield high performance gains that hot rodders and enthusiasts look for.', '', 'featured', 1, '4', '7', '8', 'superadmin', 'superadmin', 0, '2021-01-26 11:33:14', '2021-01-27 03:39:55'),
(11, 5, 9, 8, 1, '4.5\" FLEX Series Black with Polished Trim Running Boards', '65556', '18', '17', '50', 16000, 1, 16000, NULL, 'itemImage/ZmxleC1zZXJpZXMtcnVubmluZy1ib2FyZHNfMS5qcGc5ODM0NDE=.jpg', '4.5\" FLEX Series Black with Polished Trim Running Boards by Torxe™. Step up in style with Torxe™ FLEX Series Running Boards. Along with a boost into the cab with these running boards you get an upgrade in appearance accompanied by top-notch durability. The sturdy CAD designed aircraft grade aluminum structure, 4.5” wide injection molded step platform with decorative 304 stainless steel center panel, tall rubber backsplash, and attractive rounded bullnose face trim, all combine to form running boards that deliver generous non-skid support, matchless good looks, and long-lasting dependability.\r\nAny running boards can give you an assist in and out of the cab, but with Torxe™ you get more than just function, you get unsurpassed style and durability.', '', 'featured', 1, '3', '3', '4', 'superadmin', 'superadmin', 0, '2021-01-26 11:38:45', '2021-01-27 03:42:13'),
(12, 5, 10, 9, 1, 'Star Armor™ Black Side Steps', '12565', '62', '76', '50', 19000, 1, 19000, NULL, 'itemImage/c3Rhci1hcm1vci1ibGFjay1uZXJmLWJhcnNfMS5qcGc4NTI1MTE=.jpg', 'Star Armor™ Black Side Steps by Tyger®. Tyger auto focus on developing premium aftermarket auto parts that meet or exceed OE quality standards providing extra protection for your vehicle. All Tyger auto parts are covered with No-Hassle warranty and will make your vehicle stand out on the street!\r\nTyger is here with excellent products that are available at a competitive price. The company does its utmost to provide the best possible solutions for your needs. All products by Tyger are made with expert care and created by professionals to meet all your requirements. Tyger does not accept compromises when it is going about quality, so you can be sure that all products have only first-rate quality. With many years of manufacturing experience, Tyger is the name you can trust.', '', 'featured', 1, '3', '4', '3', 'superadmin', 'superadmin', 0, '2021-01-26 11:43:34', '2021-01-27 03:42:30'),
(13, 6, 11, 10, 1, 'BIZOL Brake Fluid DOT 4', '353223363', '23', '35', '63', 450, 1, 600, 400, 'itemImage/QklaT0wgQlJBS0UgRkxVSUQgRE9UIDQg4oCTIDUwMCBNTCBTWU5USEVUSUMuanBnMzQ4ODAz.jpg', 'BIZOL Brake Fluid DOT 4 is a fully synthetic high-performance brake fluid for use in all hydraulic brake systems of passenger cars and commercial vehicles. Because of the optimum combination of the synthetic base with a modern additive package, it reliably protects from corrosion as well as oxidation. Extends the life cycle of the components of brake systems. Demonstrates outstanding wet and dry boiling points, which guarantee secure braking. Also suitable for the application in brake systems with antilock (ABS). Does not damage metal, plastic, and rubber.', '', 'featured', 1, '3', '5', '6', 'superadmin', 'superadmin', 0, '2021-01-26 11:55:31', '2021-05-30 10:36:07'),
(14, 7, 12, 11, 1, 'GT-R Series CCM-R Cross Drilled 2-Piece Rotor Brake Kit', '123255', '13', '35', '22', 16700, 1, 16700, NULL, 'itemImage/QnJlbWJvwq4gLSBHVC1SIFNlcmllcyBDQ00tUiBDcm9zcyBEcmlsbGVkIDItUGllY2UgUm90b3IgQnJha2UgS2l0LmpwZzcyMTI4Ng==.jpg', 'GT-R Series CCM-R Cross Drilled 2-Piece Rotor Brake Kit by Brembo®. Quantity: 1 Pair. Upgrade your OE (Original Equipment) brakes to Brembo, the world\'s finest braking system. With Brembo you\'ll get improved pedal feel, modulation, and control of braking performance from initial application through ABS intervention. Large diameter carbon ceramic rotors and rigid, fixed multi-piston calipers greatly improve brake performance, heat dissipation and reduce brake fade. This kit is easy to install and will work seamlessly with your factory master cylinder, ABS, and traction control system.\r\nYour high performance car should stop as well as it goes; unfortunately your stock brake system isn’t up to the task. Sure, it’s okay for casual driving, but push your car through the twistys on a deserted road, or take your car to a track day, and it won’t be long before you’re experiencing brake fade, poor pedal feel, and increased stopping distances. Get the most sophisticated high performance braking system ever made for the road, the Brembo GT-R. The Brembo GT-R is just one step removed from Brembo’s full race braking system. It uses the same style aerospace aluminum billet, monobloc calipers and 2-piece, floating rotors. Brembo engineers design each brake system upgrade for the specific vehicle and driving conditions. They put the optimum combination together based on a thorough knowledge of OE braking systems and the use of an unlimited range of caliper, piston, friction material, and disc combinations. With a Brembo system you’ll experience improved pedal feel, better brake modulation, and improved brake performance. Braking action will be noticeably more immediate and decisive, and it will remain consistent even during race track use. And a Brembo system is easy to install. It comes with everything required for installation, and it’s fully compatible with your car’s master cylinder, ABS and traction control system', '', 'featured', 1, '1', '1', '1', 'superadmin', 'superadmin', 0, '2021-01-27 05:25:34', '2021-01-27 05:25:34'),
(15, 7, 12, 12, 2, 'Stage 5 Super Street Dimpled and Slotted Brake Kit', '69495959', '10', '35', '22', 11800, 1, 11800, NULL, 'itemImage/RUJDwq4gLSBTdGFnZSA1IFN1cGVyIFN0cmVldCBEaW1wbGVkIGFuZCBTbG90dGVkIEJyYWtlIEtpdC5qcGc0NDM0NTY=.jpg', 'Stage 5 Super Street Dimpled and Slotted Brake Kit by EBC®. Includes: 3GD Series Dimpled and Slotted Sport Rotors and Yellowstuff Brake Pads. The EBC Stage 5 SuperStreet Brake Kit is designed for those looking for heavy-duty high gripping pads and rotors. Thanks to the 4000 Series Yellowstuff Street and Track Pads matched with some of the coolest rotors you\'re sure to get smooth, consistent braking every time you hit the brake pedal. The anodized layer is designed to disappear in the area that the brake pads contact the rotor.\r\nEBC pioneered brake rotors with dimple-drilled round indents decades ago to provide a solution to cracking problems that sometimes plague perforated rotors operating under high stress and heat conditions. What makes the 3GD Series Dimpled and Slotted Sport Rotors superior is the presence of both these dimpled indents and straight vent slots. Combined, they provide the superior expulsion of heat, water, brake dust, and friction gas that is needed to keep rotors cool and functional during street performance driving in any weather. Additionally, 3GD rotors feature a wider vented aperture for air to pass between both rotor sides, so metal expands evenly during use and the chance of warpage is minimized. 3GD rotors are designed for use with EBC Greenstuff™ 4x4 brake pads, Greenstuff™ 2000 compact car pads, Yellowstuff™ heavy duty 4x4 brake pads, and Yellowstuff™ / Redstuff™ pads created for shorter high performance street or track runs and drifting. 3GD brake rotors are anodized to prevent corrosion, and rotors should be fully ready for use after the first 500 miles of moderate brake application', '', 'featured', 1, '2', '2', '2', 'superadmin', 'superadmin', 0, '2021-01-27 05:35:32', '2021-01-27 05:35:32'),
(16, 7, 13, 13, 1, 'AeroRotor™ Drilled Brake Rotors', '21115456', '13', '35', '22', 66300, 1, 66300, NULL, 'itemImage/U3RvcFRlY2jCriAtIEFlcm9Sb3RvcuKEoiBEcmlsbGVkIEJyYWtlIFJvdG9ycy5qcGc4OTg2NTM=.jpg', 'AeroRotor™ Drilled Brake Rotors by StopTech®. Rotor Construction: 2-Piece. Rotor Style: Drilled. StopTech® AeroRotor® Replacement Kits (ARK) are designed to replace your vehicle\'s original factory rotors, while retaining the factory brake calipers. Although the ARK is the same diameter and thickness as the factory rotors, it offers improved cooling, braking, and handling. \r\nThe directional, floating AeroRotors allow independent expansion of the rotor and hat without \"coning,\" thanks to elongated drive pin holes. ARK components include AeroRotor friction rings with patented internal vane design, pre-assembled to billet aluminium AeroHats with directional stand-offs that optimize cooling airflow. The patented AeroRotor vane design pushes up to 80% more air than factory rotors for better cooling and reduced fade on the track.', '', 'featured', 1, '3', '3', '4', 'superadmin', 'superadmin', 0, '2021-01-27 05:58:44', '2021-01-27 05:58:44'),
(17, 7, 13, 12, 1, 'High Carbon Blade Sport Slotted Brake Rotors', '5456656', '18', '35', '20', 32300, 1, 32300, NULL, 'itemImage/RUJDwq4gLSBIaWdoIENhcmJvbiBCbGFkZSBTcG9ydCBTbG90dGVkIEJyYWtlIFJvdG9ycy5qcGc2MTg3MTE=.jpg', 'High Carbon Blade Sport Slotted Brake Rotors by EBC®. Sold In Pairs. These replacement brake rotors are constructed from iron with high carbon and silicone content to reduce thermal buildup, brake noise, vibration, and wear. V-shaped slots expel more heat, dust, water, and gases and are designed to indicate rotors are worn when they wear away completely. Powder coat finish provides corrosion resistance on non-contact areas. Designed for use with EBC green, yellow, red, and blue pads. The anodized layer is designed to disappear in the area that the brake pads contact the rotor.\r\nEBC High Carbon Blade Sport Rotors are blended to offer performance drivers the absolute lowest amount of brake shudder, noise and heat buildup. Unlike brake rotors from competitors, High Carbon Blade Sport Rotors are cast from \"gray\" iron which features a high percentage of carbon (roughly 4 percent) and silicone which leads to the formation of graphite during the curing process at EBC\'s factory. When graphite is present, the rotor itself takes on qualities of a denser, softer material. Heat is more evenly dispersed to reduce warping, cracks are less likely, and vibration-related noise is greatly reduced. High Carbon Blade rotors are also powder coated with a patented Geomet finish to keep corrosion at bay, and rotors should be fully ready for performance driving after a 500 mile break-in period.', '', 'featured', 1, '3', '4', '3', 'superadmin', 'superadmin', 0, '2021-01-27 06:13:19', '2021-01-27 06:13:19'),
(18, 8, 14, 14, 2, 'Primo Series Full Size Truck Seat Covers', '23365656', '18', '17', '22', 9340, 1, 9340, NULL, 'itemImage/Uml4eHXihKIgLSBQcmltbyBTZXJpZXMgRnVsbCBTaXplIFRydWNrIFNlYXQgQ292ZXJzLmpwZzc0NzQwNQ==.jpg', 'Universal Primo Series Full Size Truck Seat Covers by Rixxu™. Sold as pair. Driving comfort, premium appearance, and maximum protection – you get them all with Rixxu™ Primo Series Seat Covers. Generous padding, integral lumbar support, smart styling, quality materials, and the most complete coverage are combined in seat covers expressly designed for drivers that log a lot of seat time and want comfortable support and an attractive addition to the cabin that will provide superior protection against spills, stains, abrasion and other damage that could cause expensive harm to original upholstery. Available for both front and rear seats, Primo series seat covers install in minutes with elastic straps and quick-connect buckles, Hook and Loop fasteners and sturdy zippers. Separate headrest covers allow easy headrest adjustment for optimal comfort and safety.', '', 'featured', 1, '3', '5', '6', 'superadmin', 'superadmin', 0, '2021-01-27 06:31:59', '2021-01-27 06:31:59'),
(19, 8, 14, 14, 2, 'Super Sport Series Seat Covers', '13235656', '18', '23', '20', 8500, 1, 8500, NULL, 'itemImage/Uml4eHXihKIgLSBTdXBlciBTcG9ydCBTZXJpZXMgU2VhdCBDb3ZlcnMuanBnNDI4OTA3.jpg', 'Universal Super Sport Series Seat Covers by Rixxu™. If the cabin doesn’t complement the rest of your performance machine, Super Sport Series seat covers from Rixxu™ are the affordable way to add driving excitement to your interior. Available in 6 different 2-tone color schemes, these easy to install, universal fit seat covers will impart a high-performance look to any vehicle. They’re constructed with durable vinyl leatherette and pleated fabric center sections, and take just minutes to install with elastic straps and quick-connect buckles, Hook and Loop fasteners and sturdy zippers. Separate headrest covers allow easy headrest adjustment for optimal comfort and safety. And once in place they’ll guard against spills, stains, abrasion and other damage that could otherwise cause expensive harm to your original upholstery.', '', 'featured', 1, '4', '6', '7', 'superadmin', 'superadmin', 0, '2021-01-27 06:48:27', '2021-01-27 06:48:27'),
(20, 9, 15, 15, 1, 'Kagu Floor Liners', '626565954', '18', '20', '20', 4200, 1, 4200, NULL, 'itemImage/M0QgTUFYcGlkZXLCriAtIEthZ3UgRmxvb3IgTGluZXJzLmpwZzQzMjkyMw==.jpg', 'Kagu Floor Liners by 3D MAXpider®. Carbon Fiber embossed pattern. Unlike the traditional floor liners with heavy weights, commercial rubbery looking. 3D KAGU all-weather custom fit floor liners are the revolutionary interior protection for your vehicles with an innovative, unique three-layer structure. The digitized three dimensional design measured to exact cabin contours of your vehicle for trapping mess and spills', '', 'featured', 1, '4', '7', '8', 'superadmin', 'superadmin', 0, '2021-01-27 07:03:17', '2021-01-27 07:03:17'),
(21, 9, 15, 16, 1, 'All Season 1st Row-Over the Hump Black Floor Mat', '464646', '18', '25', '20', 4070, 1, 4070, NULL, 'itemImage/RGVlIFplZcKuIC0gQWxsIFNlYXNvbiAxc3QgUm93LU92ZXIgdGhlIEh1bXAgQmxhY2sgRmxvb3IgTWF0LmpwZzk0NjEwMQ==.jpg', 'Universal All Season 1st Row-Over the Hump Black Floor Mat by Dee Zee®. 1 Piece. Size: 61\" x 27\". This one-piece full width rubber floor mat is designed to wrap over center tunnels and provide full coverage from driver side to passenger side foot well areas. Fully protects the carpeted interior of your vehicle from water, mud, snow, and general wear from heeled shoes. Deep grooves trap and hold all muck while rubber cleats on the underside anchor into carpet surfaces to prevent sliding.', '', 'featured', 1, '4', '8', '9', 'superadmin', 'superadmin', 0, '2021-01-27 07:13:44', '2021-01-27 07:13:44'),
(22, 9, 16, 17, 1, 'Logo  Mats', '655665', '18', '26', '20', 5500, 1, 5500, NULL, 'itemImage/TGxveWTCriAtIFVsdGltYXTihKIgTWF0cy5qcGcxMDIzOQ==.jpg', 'Ultimat™ Custom Fit Floor Mats by Lloyd®. The plush Ultimat was designed specifically for automotive use. After 30 years it is still the best-selling custom fit logo mat in the market. The Ultimat is a deep tuft, luxurious mat, available in a huge selection of colors. These top quality mats are fully customizable, with an almost unlimited choice of factory logos or custom embroidery.\r\nLloyd Mats® (Lloyd) is the largest U.S. manufacturer of custom fit floor mats. The company started business in 1974. In 1999 Lloyd\'s employees purchased 100% of Lloyd\'s shares under a qualified Employee Stock Ownership Program. This makes for unsurpassed customer service and attention to detail, with every employee taking responsibility for his or her work as any good business owner does. Lloyd Mats are all made in a large plant in Los Angeles, California. Mat patterns are digitized and the mats are cut to perfect custom fit using AutoCAD controlled, ultrasonic cutting equipment. Development of mat and embroidery computer programs and the actual manufacture of the mats and the mat embroidery are all performed in Lloyd\'s plant, to ensure that all patterns and mats meet the high and strict quality standards that have made Lloyd Mats the undisputed leader in the custom car mat industry.', '', 'featured', 1, '4', '8', '9', 'superadmin', 'superadmin', 0, '2021-01-27 08:32:46', '2021-01-27 08:32:46'),
(23, 9, 16, 18, 1, 'Honda Elite Series Floor logo Mats', '564548', '18', '25', '22', 3200, 1, 3200, NULL, 'itemImage/UGxhc3RpY29sb3LCriAtIEhvbmRhIEVsaXRlIFNlcmllcyBGbG9vci5qcGczOTc3NTc=.jpg', 'Universal Honda Elite Series Floor Mats by Plasticolor®. Plasticolor floor mats can be easily removed and washed using soap and water. They fit most domestic and import vehicles, and have a textured surface that provides extra traction. The underside of each mat is also nibbed to keep it firmly in place without sliding.\r\nPlasticolor has been supplying the automotive aftermarket with high quality automotive accessories for over 40 years. Their success in the market comes from an uncompromising commitment in designing on-trend, high quality automotive accessories and combining them with today\'s most popular and iconic brands. Although Plasticolor began as a floor mat manufacturer, in addition to floor mats they produce many other product categories today', '', 'featured', 1, '2', '2', '2', 'superadmin', 'superadmin', 0, '2021-01-27 08:40:56', '2021-01-27 08:40:56'),
(24, 11, 17, 19, 2, 'Ford 1 725 55 2 Genuine Fuel Filter', '5456656', '18', '20', '22', 1500, 1, 1500, NULL, 'itemImage/Rk9SRCAxIDcyNSA1NSAyIEdFTlVJTkUgRlVFTCBGSUxURVIgKEVMRU1FTlQpLnBuZzU2NjA1OA==.png', 'Manufacturer Part Number: 1 725 55 2\r\nGPN/OEM NO: 1 725 55 2\r\nPackage Quantity: 1 Piece\r\nPlace of Origin: N/A\r\nWarranty: N/A\r\nItem Grade: OEM Standard\r\nQuality: High quality\r\nFuel Type: Diesel\r\nMaterial: Metal\r\nColor: High Capacity\r\nInner Diameter: 30\r\nInner Diameter: 27/12\r\nLEngth:84\r\nOutside Diameter: 83\r\nVehicle Type: Passenger Vehicle (PICK UP)', '', 'featured', 1, '3', '3', '4', 'superadmin', 'superadmin', 0, '2021-01-27 08:53:34', '2021-01-27 08:53:34'),
(25, 11, 17, 20, 2, 'Mitsubishi 1770A053 Genuine Diesel Fuel Filter', '66564', '43', '47', '45', 1850, 1, 1850, NULL, 'itemImage/TUlUU1VCSVNISSAxNzcwQTA1MyBHRU5VSU5FIERJRVNFTCBGVUVMIEZJTFRFUiAoU1BBSU4tT04pLnBuZzU5MjYyOA==.png', 'Manufacturer Part Number: 1770A053\r\nGPN/OEM NO: 1770A053\r\nPackage Quantity: 1 Piece\r\nPlace of Origin: N/A\r\nWarranty: N/A\r\nItem Grade: OEM Standard\r\nQuality: High quality\r\nFuel Type: Diesel\r\nMaterial: Metal\r\nColor: Black\r\nHEight: 137\r\nOutside Diameter: 90\r\nO-Ring Gasket:62.5X56.5\r\nThread Nut Size: M36X1.5\r\nThread Size: 3/4″x16 UNF', '', 'featured', 1, '4', '6', '7', 'superadmin', 'superadmin', 0, '2021-01-27 09:01:25', '2021-01-27 09:01:25'),
(26, 11, 17, 21, 2, 'Toyota 23300-75140 Genuine Fuel Filter', '322366', '18', '17', '22', 2200, 1, 2200, NULL, 'itemImage/VE9ZT1RBIDIzMzAwLTc1MTQwIEdFTlVJTkUgRlVFTCBGSUxURVIuanBnMjk3MTM3.jpg', 'The longevity of your engine, and smooth performance of your vehicle relies on a clean flow of fuel. It is the role of fuel filters to capture any impurities that may have travelled into your fuel tank. The quality of a Fuel Filter can be best gauged by its ability to trap even the tiniest impurities.Toyota Genuine Fuel Filters trap the smallest of particles. The thorough filtering process ensures clean fuel and smooth engine operation.Toyota Genuine Fuel Filters are designed specifically for each Toyota model, to fit fuel lines precisely and therefore trap the tiniest of impurities.Unlike some non-genuine fuel filters, Toyota Genuine Fuel Filters are constructed of high quality materials, which are both airtight and highly heat resistant - an important feature with petrol in the hot environment of an engine bay.Toyota Genuine Fuel Filters are engineered to catch particles as small as ten microns, yet still maintain a smooth flow of fuel. Lesser quality filters use poorly constructed filter papers, which allow larger impurities to clog and corrode the engine, causing engine malfunction.', '', 'featured', 1, '3', '3', '5', 'superadmin', 'superadmin', 0, '2021-01-27 09:16:38', '2021-01-28 04:32:22'),
(27, 11, 18, 21, 1, 'Toyota 23209-21040 Genuine Fuel Injector', '25656', '18', '24', '22', 18000, 1, 18000, NULL, 'itemImage/VE9ZT1RBIDIzMjA5LTIxMDQwIEdFTlVJTkUgRlVFTCBJTkpFQ1RPUiwgUEFDSyBPRiAxICg0UENTKS5qcGczMTgxNDk=.jpg', 'Your vehicle deserves only genuine OEM Toyota parts and accessories. To ensure reliability, purchase Toyota part # 23209-21040 INJECTOR ASSY, FUEL . Our Toyota parts and accessories are expedited directly from authorized Toyota dealers strategically located all across the U.S. and are backed by the manufacturer\'s 12 month, 12,000 mile warranty. OEM Toyota parts are the best for restoring your vehicle to factory condition performance. This part fits specific Toyota Yaris models.\r\n\r\nAffordable, reliable and built to last, Toyota part # 2320921040 INJECTOR ASSY, FUEL stands out as the smart option. Toyota Parts Deal is your prime online source with the biggest and best selection of genuine Toyota parts and accessories at giant discounted prices. We have the OEM Toyota parts and accessories you need at the lowest possible prices. Toyota Parts Deal has you covered no matter what type of Toyota vehicle you drive.', '', 'featured', 1, '3', '5', '6', 'superadmin', 'superadmin', 0, '2021-01-27 09:32:38', '2021-01-28 03:17:08'),
(28, 11, 18, 21, 1, 'Toyota 23209-39215 Genuine Fuel Injector', '325656', '26', '24', '22', 6800, 1, 6800, NULL, 'itemImage/VE9ZT1RBIDIzMjA5LTM5MjE1IEdFTlVJTkUgRlVFTCBJTkpFQ1RPUiwgUEFDSyBPRiAxICg2UENTKS5wbmc1MjA5OQ==.png', 'Fits: 00-04 for TOYOTA Corolla & 00-05 for TOYOTA Celica 03-06 Matrix & Pontiac Vibe & 00-02 Chevrolet Prizm 1.8L L4 Gas DOHC. Please Confirm This Part Fits Your Vehicle Before Purchasing (See a Fitment Note after \"Select your Vehicle\" Above)\r\nAll the Components are produced under strictly observed and meet or exceed OEM performance requirements in Manufacturing and Material\r\nInterchange Part Numbers: 23250-0D040, 23250-22040, 23209-0D040\r\nPre-Prepared fuel injectors and O-rings, direct replacement of your vehicle\'s original parts for easier installation\r\nLocal US friendly after-service team to resolve your issues in time, parts have 2 years or 40000 miles warranty', '', 'special', 1, '3', '4', '3', 'superadmin', 'superadmin', 0, '2021-01-27 09:44:28', '2021-01-27 11:03:39'),
(29, 12, 19, 24, 2, 'Front Grilles', '1656', '13', '35', '22', 24000, 1, 24000, NULL, 'itemImage/ODM0MjMxYy0yXzEuanBnODkyMzQx.jpg', 'Single-Slat Kidney Grilles by AutoTecknic®. Developed and engineered with the OEM standard as the framework, all AutoTecknic front grilles are made with 100% non-recycled raw plastic that results in overall durable construction with strong clips and tabs for a secure and seamless fit. As an AutoTecknic standard, each outer ring and grille slat are individually finished with precision that yields a product of superior paint quality fit to accentuate any vehicle.', '', 'featured', 1, '3', '3', '5', 'superadmin', 'superadmin', 0, '2021-01-27 09:59:15', '2021-01-27 10:17:40'),
(30, 12, 19, 23, 2, 'Grilles', '23626262', '18', '24', '22', 23000, 1, 23000, NULL, 'itemImage/Y2gxMjAwMTk5XzEuanBnMTcyNDAx.jpg', 'Grilles by Replace®. The grille is vulnerable to airborne debris, which can wear the paint and chrome and cause cracks and other damage. And even a minor front end collision can severely damage a grille. If you\'re in the market for new grille and you\'ve been stunned by the price at the dealer, Replace has quality replacement grilles that are similar to original equipment (OE) for much less than the OE price.', '', 'featured', 1, '4', '8', '9', 'superadmin', 'superadmin', 0, '2021-01-27 10:09:23', '2021-01-27 10:09:23'),
(31, 13, 20, 25, 2, 'Cowl Heat Reduction Fiberglass Hood', '26556', '18', '25', '22', 67000, 1, 67000, NULL, 'itemImage/amVlcDA3aG9vZC13Zi0wMV8xLmpwZzU0Mjk5Mw==.jpg', 'Cowl Heat Reduction Hood by ProMaxx®. Material: Fiberglass. Finish: Unpainted. This hood uses 2 sets of fully functional vents to expel the maximum amount of heat to reduce under hood temperatures. The 2 vents on the side of the hood are strategically placed to give heat being pushed back towards the firewall a way to exit the engine bay when the JK is traveling at a high speed. A second set of vents, running the full length of the hood, expel rising heat from the entire engine bay when the JK is traveling at slower speeds.', '', 'featured', 1, '4', '7', '8', 'superadmin', 'superadmin', 0, '2021-01-27 10:37:27', '2021-01-27 10:37:27'),
(32, 14, 21, 26, 1, 'Factory Replacement Tail Lights', '565466565', '18', '20', '22', 2800, 1, 2800, NULL, 'itemImage/ZmFjdG9yeS10YWlsLWxpZ2h0c18xLmpwZzc2MjEyMw==.jpg', 'Factory Replacement Tail Lights by TYC®. Whenever you\'re on the road, you rely on your tail lights to show other drivers whether you\'re about to stop or turn. Because non-functional tail lights endanger you and your passengers, do replace your damaged lights as soon as possible. TYC tail lights are a direct replacement for the stock units that offer OE quality without the OE price.', '', 'featured', 1, '2', '2', '2', 'superadmin', 'superadmin', 0, '2021-01-27 10:59:25', '2021-01-27 10:59:25'),
(33, 14, 22, 27, 1, 'Euro Tail Lights', '266656', '18', '25', '22', 4800, 1, 4800, NULL, 'itemImage/ODgtMTAwMTA1OV8xLmpwZzM5NDQzNA==.jpg', 'Euro Tail Lights by Lumen®. Pick out your valuable possession from the rest of the rolling masses and give it that saucy look it deserves by getting these top quality Euro tail lights by Lumen. Featuring an advanced light design and tough construction, these lights are proven to deliver bright illumination needed to alert other drivers of your next move and keep your vehicle conspicuous.', '', 'featured', 1, '1', '1', '1', 'superadmin', 'superadmin', 0, '2021-01-28 07:06:57', '2021-01-28 07:06:57'),
(34, 15, 23, 28, 1, 'Stormproof Custom Car Cover', '66565', '18', '35', '22', 7000, 1, 7000, NULL, 'itemImage/c3Rvcm1wcm9vZi1jYXItY292ZXJfMS5qcGc2NjUxNzc=.jpg', 'Stormproof Custom Car Cover by Coverking®. Stormproof Custom Car Cover is a unique, industry leading, multi-purpose cover that is both light weight and extremely durable. Manufactured to the exact specifications of your vehicle, this cover provides the best all around protection against extreme weather.\r\nPerfect for those living in the northwest region, this car cover also provides substantial protection against UV rays, snow, rain and other pollutants. On top of that, this fabric requires no coatings that wear off - it\'s characteristics are built-in. This cover can be used both indoors and outdoors.', '', 'featured', 1, '1', '1', '1', 'superadmin', 'superadmin', 0, '2021-01-28 08:31:27', '2021-01-28 08:31:27'),
(35, 15, 23, 28, 1, 'Gray Custom Car Cover', '54548748', '55', '68', '59', 8740, 1, 8740, NULL, 'itemImage/Y292ZXJib25kLTQtY2FyLWNvdmVyXzEuanBnNzIxNDk2.jpg', 'Gray Custom Car Cover by Coverking®. Built of four layers, this type of cover delivers breathability, both indoor and outdoor protection against UV rays, dust and pollutants and even light hail. Not only that - it will protect from minor scratches, dents and dings. However this cover type is not recommended for everyday use as it tends to be a bit more bulky, compared to others, yet providing ultimate protection. Custom logos are available as an option for this product.', '', 'featured', 1, '1', '1', '1', 'superadmin', 'superadmin', 0, '2021-01-28 08:43:57', '2021-01-28 08:43:57'),
(36, 16, 24, 29, 2, 'Air Intake Kit', '45445555', '24', '26', '22', 14340, 1, 14340, NULL, 'itemImage/NTctMTUzOV8xLmpwZzg0MzA2MA==.jpg', '57 Series Generation II Air Intake Kit by K&N®. This kit improves airflow into your engine. It includes a K&N air filter and a custom designed air intake tube. The K&N filter increases the airflow and the intake tube smoothes that airflow into the engine. The result is more horsepower and torque, and better acceleration you can feel.57 Series Generation II Air Intake Kit by K&N®. This kit improves airflow into your engine. It includes a K&N air filter and a custom designed air intake tube. The K&N filter increases the airflow and the intake tube smoothes that airflow into the engine. The result is more horsepower and torque, and better acceleration you can feel.', '', 'featured', 1, '3', '3', '4', 'superadmin', 'superadmin', 0, '2021-01-28 09:18:01', '2021-01-28 09:18:01'),
(37, 17, 25, 30, 2, 'Turbo Kit', '12154', '18', '25', '22', 92700, 1, 92700, NULL, 'itemImage/NzcyNDQxLTUwMDJzXzEuanBnNDA2MjAx.jpg', 'Designed utilizing the latest technology, this product by Garrett features premium quality and will perform better than advertised. Perfect for your vehicle and lifestyle, it is manufactured to meet or exceed stringent industry standards.A turbo is a high technology product that requires superior design and intensive capital to produce. It must meet the severe requirement that only a world class manufacturer like Garrett® can achieve. Garrett is one of the few turbo-charging manufacturers that subjects our turbos to several OE qualification tests. These turbocharging \"qual tests\" ensure Garrett produces a safe and reliable turbo for OE applications.', '', 'featured', 1, '3', '4', '3', 'superadmin', 'superadmin', 0, '2021-01-28 09:36:05', '2021-01-28 09:36:05'),
(38, 17, 25, 31, 1, 'S5-210 Series Supercharger System', '112654', '18', '20', '22', 95800, 1, 95800, NULL, 'itemImage/MjY0YTEwMDdfMS5qcGc4NDA2OTg=.jpg', 'If you are looking to get optimum torque and performance from your vehicle, Sprintex® is ready to help you out with this. Headquartered in Auburn Hills, MI, it manufactures superior superchargers which provide a robust increase in power and improved torque. The company uses only top grade materials and state-of-the-art machinery to ensure excellent quality and reliability. As a result, Sprintex has earned a well-deserved reputation as an industry leader in the design and manufacture of supercharger systems. The company has a solution for everyone no matter what vehicle you drive.', '', 'featured', 1, '3', '5', '6', 'superadmin', 'superadmin', 0, '2021-01-28 10:02:48', '2021-01-28 10:02:48'),
(39, 18, 26, 32, 1, 'Airbag Replacement Center Mark Steering Wheel', '123456', '13', '35', '22', 17200, 1, 17200, NULL, 'itemImage/NjEwNDBfMS5qcGc2NTEwNTA=.jpg', 'Airbag Replacement Center Mark Steering Wheel by Grant®. This is a custom-built version of your vehicle’s original equipment steering wheel upgraded with stylish leather and center mark. Airbag Replacement Center Mark Steering Wheel by Grant®. This is a custom-built version of your vehicle’s original equipment steering wheel upgraded with stylish leather and center mark. Center airbag and any control switches are transferred from your old steering wheel.Center airbag and any control switches are transferred from your old steering wheel.', '', 'featured', 1, '3', '3', '5', 'superadmin', 'superadmin', 0, '2021-01-28 10:29:03', '2021-01-28 10:29:03'),
(40, 19, 27, 33, 1, '3\" Bull Bar', '55686', '13', '35', '22', 23850, 1, 23850, NULL, 'itemImage/Y2hyb21lLWJ1bGwtYmFyLXdpdGgtc2tpZC1wbGF0ZV8xLmpwZzYyMzQ5Mg==.jpg', '3\" Bull Bar by Black Horse®. If you want to enhance your vehicle\'s front-end protection and add a perfect finishing touch to its exterior, go with this great bull bar. The part is constructed of heavy-duty steel tubing to provide years of dependable service.', '', 'featured', 1, '4', '8', '9', 'superadmin', 'superadmin', 0, '2021-01-28 11:19:29', '2021-01-28 11:19:29'),
(41, 19, 28, 34, 2, '1-Piece Design Grille Guard', '4656564', '18', '25', '20', 25000, 1, 25000, NULL, 'itemImage/YXJpZXMtc3Mtb25lLXBpZWNlLWdyaWxsZS1ndWFyZF8xLmpwZzg3NjkxNg==.jpg', '1-Piece Design Grille Guard by Aries®. The Aries One-Piece Front Guard design is adapted to each application, providing an OEM accessory look that universal front guards cannot achieve. The product offers both real protection and elegance. This guard features predrilled holes for auxiliary lights and bolt on installation, so it will take just a few minutes to install it.', '', 'featured', 1, '4', '7', '8', 'superadmin', 'superadmin', 0, '2021-01-28 12:09:26', '2021-01-28 12:09:26'),
(42, 11, 17, 1, 4, 'BMW Quartz 9000 Energy 0W-40 SN/CF Engine Oil', '111111111', '10', '15', '5', 5000, 2, 5000, NULL, 'itemImage/Qk1XIE0gVFdJTiBQT1dFUiBUVVJCTyBTQUUgMFctNDAgRU5HSU5FIE9JTC0gMSBMVFIgRlVMTCBTWU5USEVUSUMucG5nMTQ3MDA4.png', 'xtremely high level of engine protection, ensuring that all engine parts last for a long time. Protection is greater than 20% at the official European manufacturers’ wear tests.\r\nProtection for petrol engine pollution-control systems: optimises the way in which three-way catalytic converters work, preventing them from getting clogged up with deposits.\r\nReduces emissions of NOx, HC and CO in particular.', '', 'bestrated', 1, '1', '1', '1', 'superadmin', 'superadmin', 1, '2021-01-31 05:06:01', '2021-01-31 05:42:49'),
